draw:
var pad = 34;
var top = 26;
var floorY = H - 22;
var tankX = pad, tankW = (W - pad * 2) * 0.52;
var depthMax = 30;
var sy = (floorY - top) / depthMax;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

// tank walls and water
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(tankX, top - 8);
ctx.lineTo(tankX, floorY);
ctx.lineTo(tankX + tankW, floorY);
ctx.lineTo(tankX + tankW, top - 8);
ctx.stroke();

// wavy surface
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 40; i++) {
  var x = tankX + tankW * i / 40;
  var y = top + 2.0 * Math.sin(i * 0.55 + t * 1.6);
  i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
}
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("surface, p = p0", tankX + 6, top - 14);

// depth marker
var d = p.depth;
var dy = top + d * sy;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(tankX, dy);
ctx.lineTo(tankX + tankW, dy);
ctx.stroke();
ctx.setLineDash([]);

// the column of fluid above the point
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.25;
ctx.fillRect(tankX + tankW * 0.30, top, tankW * 0.16, d * sy);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure;
ctx.strokeRect(tankX + tankW * 0.30, top, tankW * 0.16, d * sy);

var cx = tankX + tankW * 0.38;
// weight arrow of the column
ctx.strokeStyle = C.ink;
ctx.beginPath();
ctx.moveTo(cx, top + d * sy * 0.35);
ctx.lineTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx - 3.5, top + d * sy * 0.35 + 16);
ctx.moveTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx + 3.5, top + d * sy * 0.35 + 16);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("weight of column", cx + 8, top + d * sy * 0.35 + 12);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillText("depth h = " + d.toFixed(1) + " m", tankX + 6, dy + 14);

// graph of pressure vs depth on the right
var gx0 = tankX + tankW + 46, gx1 = W - 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, top);
ctx.lineTo(gx0, floorY);
ctx.lineTo(gx1, floorY);
ctx.stroke();

var pAtm = 101000;
var pMax = pAtm + p.rho * 9.8 * depthMax;
var gw = gx1 - gx0;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 60; k++) {
  var hh = depthMax * k / 60;
  var pp = pAtm + p.rho * 9.8 * hh;
  var X = gx0 + gw * pp / pMax;
  var Y = top + hh * sy;
  k === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();

var pAbs = pAtm + p.rho * 9.8 * d;
var mx = gx0 + gw * pAbs / pMax;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(mx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(gx0, dy);
ctx.lineTo(mx, dy);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.fillText("pressure", gx0 + 4, floorY + 12);
ctx.save();
ctx.translate(gx0 - 12, (top + floorY) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("depth", 0, 0);
ctx.restore();
ctx.textAlign = "left";

out.note = "gauge " + (p.rho * 9.8 * d / 1000).toFixed(1) + " kPa, absolute " +
  (pAbs / 1000).toFixed(1) + " kPa (" + (pAbs / pAtm).toFixed(2) + " atmospheres)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var cx = W * 0.40;
var top = H * 0.28, bot = H * 0.74;
var bw = Math.min(W * 0.26, 150);
var left = cx - bw / 2, right = cx + bw / 2;

// water surface
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 60; i++) {
  var x = W * i / 60;
  ctx.lineTo(x, 18 + 1.5 * Math.sin(i * 0.4));
}
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("water surface", 8, 30);

// block
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.strokeRect(left, top, bw, bot - top);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("block", cx, (top + bot) / 2);
ctx.textAlign = "left";

function arrow(x0, y0, x1, y1) {
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x1 - 5 * Math.cos(a - 0.4), y1 - 5 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 5 * Math.cos(a + 0.4), y1 - 5 * Math.sin(a + 0.4));
  ctx.stroke();
}

// short arrows pushing down on the top face
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.4;
for (var j = 0; j < 4; j++) {
  var x = left + bw * (j + 0.5) / 4;
  arrow(x, top - 20, x, top - 2);
}
ctx.fillStyle = C.figure;
ctx.fillText("small push down: p at the top face", right + 10, top - 12);

// long arrows pushing up on the bottom face
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.4;
for (var j2 = 0; j2 < 4; j2++) {
  var x2 = left + bw * (j2 + 0.5) / 4;
  arrow(x2, bot + 34, x2, bot + 2);
}
ctx.fillStyle = C.accent;
ctx.fillText("bigger push up: p is larger deeper down", right + 10, bot + 18);

// sideways arrows cancel
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.2;
for (var k = 0; k < 3; k++) {
  var y = top + (bot - top) * (k + 0.5) / 3;
  arrow(left - 22, y, left - 3, y);
  arrow(right + 22, y, right + 3, y);
}
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("sides cancel", cx, bot + 44);
ctx.textAlign = "left";

// net buoyant force
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.2;
arrow(W * 0.83, (top + bot) / 2 + 34, W * 0.83, (top + bot) / 2 - 34);
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("net = buoyant force", W * 0.83, (top + bot) / 2 - 46);
ctx.fillText("= weight of displaced water", W * 0.83, (top + bot) / 2 + 48);
ctx.textAlign = "left";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var surf = H * 0.36;
var ratio = p.rhoObj / p.rhoFluid;
var floats = ratio < 1;
var frac = floats ? ratio : 1;

var bw = Math.min(W * 0.22, 120);
var bh = H * 0.30;
var cx = W * 0.42;

// water body
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.18;
ctx.fillRect(0, surf, W, H - surf - 14);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(0, H - 14);
ctx.lineTo(W, H - 14);
ctx.stroke();

// equilibrium position: top of block sits (1-frac)*bh above the surface
var yEqTop = surf - (1 - frac) * bh;

// bobbing: only if it floats, small damped-free oscillation about equilibrium
var amp = floats ? Math.min(bh * 0.18, 16) : 0;
var omega = floats ? Math.sqrt(9.8 / Math.max(ratio * bh / 40, 0.05)) : 0;
var bobPix = amp * Math.cos(t * (floats ? 2.2 + 2.0 * (1 - ratio) : 0));
var sinkPix = floats ? 0 : Math.min((H - 26 - bh - surf), 26 + 14 * Math.sin(t));
var yTop = yEqTop + bobPix + sinkPix;

// wavy surface line
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 60; i++) {
  var x = W * i / 60;
  ctx.lineTo(x, surf + 1.6 * Math.sin(i * 0.45 + t * 1.4));
}
ctx.stroke();

// block
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.6;
ctx.strokeRect(cx - bw / 2, yTop, bw, bh);
// shade submerged part
var subTop = Math.max(yTop, surf);
var subH = Math.max(0, yTop + bh - subTop);
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.22;
ctx.fillRect(cx - bw / 2, subTop, bw, subH);
ctx.globalAlpha = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("rho = " + p.rhoObj.toFixed(0), cx, yTop + bh / 2);
ctx.textAlign = "left";

function arrow(x0, y0, x1, y1) {
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x1 - 6 * Math.cos(a - 0.4), y1 - 6 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 6 * Math.cos(a + 0.4), y1 - 6 * Math.sin(a + 0.4));
  ctx.stroke();
}

// force arrows, scaled to the ratio of buoyancy to weight
var wLen = 46;
var bLen = wLen * (floats ? 1 : p.rhoFluid / p.rhoObj);
var ax = cx + bw / 2 + 34;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
arrow(ax, yTop + bh / 2, ax, yTop + bh / 2 - bLen);
ctx.fillStyle = C.accent;
ctx.fillText("buoyant force", ax + 8, yTop + bh / 2 - bLen);

ctx.strokeStyle = C.ink;
arrow(ax, yTop + bh / 2, ax, yTop + bh / 2 + wLen);
ctx.fillStyle = C.ink;
ctx.fillText("weight", ax + 8, yTop + bh / 2 + wLen);

ctx.fillStyle = C.faint;
ctx.fillText("fluid rho = " + p.rhoFluid.toFixed(0) + " kg/m3", 10, surf + 20);

if (floats) {
  out.note = "floats with " + (frac * 100).toFixed(1) + "% of its volume under water" +
    " (V_sub / V = " + ratio.toFixed(3) + ")";
} else {
  out.note = "sinks: buoyancy is only " + (100 * p.rhoFluid / p.rhoObj).toFixed(1) +
    "% of the weight, apparent weight is " + (100 * (1 - p.rhoFluid / p.rhoObj)).toFixed(1) + "% of the real one";
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var scale = (H - 60) / 0.9;   // pixels per metre of liquid
var bottomY = H - 26;
var tubeW = Math.min(W * 0.13, 52);
var gapW = Math.min(W * 0.22, 110);
var midX = W * 0.45;
var lx = midX - gapW / 2 - tubeW, rx = midX + gapW / 2;

var hOil = p.hOil;
var rhoOil = p.rhoOil;
var rhoW = 1000;
// water in right arm stands above the interface by rhoOil*hOil/rhoW
var rise = rhoOil * hOil / rhoW;

var interfaceY = bottomY - 0.22 * scale;      // interface in the left arm
var oilTopY = interfaceY - hOil * scale;
var rightY = interfaceY - rise * scale;

// tube outline
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(lx, 20); ctx.lineTo(lx, bottomY); ctx.lineTo(rx + tubeW, bottomY); ctx.lineTo(rx + tubeW, 20);
ctx.moveTo(lx + tubeW, 20); ctx.lineTo(lx + tubeW, bottomY - 16); ctx.lineTo(rx, bottomY - 16); ctx.lineTo(rx, 20);
ctx.stroke();

// water fill
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.20;
ctx.fillRect(lx + 1, interfaceY, tubeW - 2, bottomY - interfaceY - 1);
ctx.fillRect(rx + 1, rightY, tubeW - 2, bottomY - rightY - 1);
ctx.fillRect(lx + tubeW, bottomY - 16, rx - lx - tubeW, 15);
ctx.globalAlpha = 1;

// oil fill
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.fillRect(lx + 1, oilTopY, tubeW - 2, hOil * scale);
ctx.globalAlpha = 1;

// level lines
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.4;
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(lx + tubeW, interfaceY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, oilTopY); ctx.lineTo(lx + tubeW, oilTopY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx, rightY); ctx.lineTo(rx + tubeW, rightY); ctx.stroke();

// the matching-level line through the interface
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(rx + tubeW + 6, interfaceY); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.fillText("same level, same pressure", lx - 4, interfaceY + 14);

ctx.fillStyle = C.figure;
ctx.fillText("oil", lx + tubeW / 2 - 8, (oilTopY + interfaceY) / 2);
ctx.fillStyle = C.ink;
ctx.fillText("water", rx + tubeW + 6, (rightY + bottomY) / 2);

// height annotations
function dim(x, y0, y1, label) {
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x, y0); ctx.lineTo(x, y1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x - 4, y0); ctx.lineTo(x + 4, y0);
  ctx.moveTo(x - 4, y1); ctx.lineTo(x + 4, y1); ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.fillText(label, x + 6, (y0 + y1) / 2);
}
dim(lx - 16, oilTopY, interfaceY, hOil.toFixed(2) + " m oil");
dim(rx + tubeW + 40, rightY, interfaceY, rise.toFixed(3) + " m");

out.note = "rho_oil h_oil = rho_water h_water, so the water stands " +
  rise.toFixed(3) + " m above the interface";
